int getTimeType(Date time) {
    SimpleDateFormat df = new SimpleDateFormat("HH");
    String str = df.format(time);
    int a = Integer.parseInt(str);
    //上午
    if (a >= 4 && a <= 12) {
        return 1;
    }
    //下午
    if (a > 12 && a <= 24) {
        return 2;
    }
    return 1;
}

