        return(CPF.substring(0, 3) + "." + CPF.substring(3, 6) + "." +
        CPF.substring(6, 9) + "-" + CPF.substring(9, 11));
    }

	public int compareTo(Cliente titular) {
		if (this.getNome().compareTo(titular.getNome()) > 0) { // compara pelo nome
			return -1; 
