double distance(Cam16 other) {
  double dJ = getJstar() - other.getJstar();
  double dA = getAstar() - other.getAstar();
  double dB = getBstar() - other.getBstar();
  double dEPrime = Math.sqrt(dJ * dJ + dA * dA + dB * dB);
