        OAuth2User user = super.loadUser(userRequest);
        OAuth2UserInfo oAuth2UserInfo = makeOAuth2UserInfoByProvider(userRequest, user);
        return processMemberByOAuth2UserInfo(oAuth2UserInfo);
    }

